  --xt-text-sub: #d49da8; /* 温柔的雾面浅粉色 */
  --xt-accent: #e5b3be; /* 核心温润淡粉色 */
  --xt-accent-light: #f9eaec;
  --xt-font: 'Noto Serif SC', serif; 

  /* 精确缩减底栏，刚好贴合下方的英文字母与重叠圆圈 */
  padding: 16px 12px 28px !important; 
