xinshengLayout:
# 雾语蓝 - 渐变叠影论坛版
@particles rain 30

@collapse "Ⅱ ． 隙 间 白 噪" 2 .fadeInUp.delay100
@text talk1
@text talk2
@text talk3
@text talk4
@text talk5
@text talk6
@endcollapse

@collapse "Ⅰ ． 见 字 如 面" 1 .fadeInUp.delay200
@image letterImage
@text moodWord1
@text moodWord2
@text moodWord3
@quote letterConfession
@endcollapse

@collapse "Ⅲ ．  浮 生 瑣 記" 3 .fadeInUp.delay300
@list
memo1
memo2
memo3
@endcollapse

# === 隐藏论坛区 (1个主帖 + 5个顺序评论流) ===
@collapse "Ⅳ ． 雾 境 坛 喧" 4
@text forum_post_1
@text forum_reply_1
@text forum_reply_2
@text forum_reply_3
@text forum_reply_4
@text forum_reply_5
@endcollapse

# === 右下角交互开关 ===
@toggle 4
